def test_an_oversized_upload_is_rejected():
    """An upload over the size limit is refused."""
    with pytest.raises(UploadRejected, match="too large"):
        validate_upload("report.pdf", 50 * 1024 * 1024)


def test_an_uppercase_extension_is_accepted_and_lowercased():
    """A recognised extension is allowed regardless of case."""
    assert validate_upload("REPORT.PDF", 1024) == "report.pdf"


@pytest.mark.parametrize("filename", ["report.txt", "report", "report.PDFX"])
def test_a_disallowed_extension_is_rejected(filename):
    """Only .pdf, .png and .csv extensions are accepted."""
    with pytest.raises(UploadRejected, match="extension"):
        validate_upload(filename, 1024)


@pytest.mark.parametrize("filename", ["../report.pdf", "sub/report.pdf", "sub\\report.pdf"])
def test_a_path_separator_is_rejected(filename):
    """A filename containing a path separator is refused, not repaired."""
    with pytest.raises(UploadRejected, match="path separator"):
        validate_upload(filename, 1024)


def test_a_leading_dot_is_rejected():
    """A filename that starts with a dot is refused."""
    with pytest.raises(UploadRejected, match="start with a dot"):
        validate_upload(".report.pdf", 1024)


def test_the_stored_name_is_lowercased():
    """The name returned for storage is lowercased."""
    assert validate_upload("Report.Csv", 1024) == "report.csv"

